let LANG='en';
function setLang(code){
  LANG=LANGUAGES.some(l=>l.code===code)?code:'en';
  document.documentElement.lang=LANG;
}
// tr('Season {n}',{n:2}) gives the text in the chosen language with the values filled in
function tr(text,vars){
  let out=STRINGS[LANG]?.[text]||text;
  for(const k in vars||{})out=out.replaceAll('{'+k+'}',vars[k]);
  return out;
}
const langName=code=>LANGUAGES.find(l=>l.code===code)?.name||'';
const myLabels=()=>LANGUAGES.find(l=>l.code===LANG)?.labels||[];
// The language of a title's label, so a German title is searched for in German
const labelLang=label=>LANGUAGES.find(l=>l.labels.includes(label))?.code||'';
